"""Hand-specified process regressions; expected values are not generated by monitors."""
import json
import shutil
import sys
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'src'))
from plc_agent.common import digest
from plc_agent.dataset import load_tasks, validate


def cases():
    result={}
    names=['valveARun','valveBRun','valveCRun','valveDRun','mixMotorRun']
    rows=[({'valveBStart':True},'valveBRun'),({'valveBStart':True},'valveBRun'),
          ({'opeMode':True,'autoStart':True},None),({'opeMode':True,'autoStart':True},None),
          ({'opeMode':True},None),({'opeMode':True,'autoStart':True},'valveARun'),
          ({'opeMode':True,'levelSensor':50},'valveBRun'),
          ({'opeMode':True,'levelSensor':80},'mixMotorRun'),
          ({'opeMode':True,'mixMotorComplete':True},'valveDRun'),
          ({'opeMode':True},'valveDRun')]
    result['PUB015']=[(dict(estop=True,**i),{n:n==active for n in names}) for i,active in rows]
    base=dict(processLength=3,processSequence=[2,2,5,0,0,0,0,0])
    rows=[({'sensor1':True,'station1Start':True},True),
          ({'sensor2':True,'station2Complete':True},False),
          ({'sensor2':True,'station2Complete':True},False),
          ({'sensor2':True},False),({'sensor2':True,'station2Complete':True},False),
          ({'sensor2':True,'station2Complete':True},False),({'sensor2':True},False),
          ({'sensor2':True,'station2Complete':True},True),({'sensor5':True},False)]
    result['PUB016']=[(dict(base,**i),dict(conveyorLeft=False,conveyorRight=right)) for i,right in rows]
    rows=[({'SensorFeed':True},True,False,False,0),
          ({'SensorWash':True,'washComplete':True},False,False,False,0),
          ({'SensorWash':True,'washComplete':True},True,False,False,0),
          ({'SensorWeight':True},False,False,False,0),
          ({'SensorWeight':True,'weightComplete':True,'weight':150},True,False,False,525),
          ({'SensorFiring':True},False,False,False,525),
          ({'SensorFiring':True,'firingComplete':True},True,False,False,525),
          ({'SensorOutput':True},False,False,True,525),({},False,False,False,525),
          ({'SensorFeed':True},True,False,False,525),({'SensorWash':True},False,False,False,525),
          ({'SensorWash':True,'washComplete':True},True,False,False,525),
          ({'SensorWeight':True},False,False,False,525),
          ({'SensorWeight':True,'weightComplete':True,'weight':99.9},False,True,False,525),
          ({'SensorWeight':True},False,True,False,525),({},False,False,False,525)]
    result['PUB020']=[(dict(Mode=True,**i),dict(MotorForward=f,MotorReverse=False,kick=k,CompletionLight=l,firingTemp=t)) for i,f,k,l,t in rows]
    return result

def main():
    archive=ROOT/'dataset_versions/before_process_extension'
    if not archive.exists():shutil.copytree(ROOT/'dataset',archive)
    for tid,rows in cases().items():
        path=ROOT/'dataset/public'/(tid+'.json');t=json.loads(path.read_text(encoding='utf-8'))
        defaults={f['name']:False if f['type']=='BOOL' else 0 for f in t['interface'] if f['direction']=='INPUT'}
        case=dict(id='V2_process_history_regression',purpose='Mode/edge reset, repeated station or prior-batch retained setpoint regression.',steps=[dict(inputs=dict(defaults,**i),expected=o) for i,o in rows])
        t['tests']=[c for c in t['tests'] if c['id']!=case['id']]+[case]
        t['specification_contract']['executable_monitor']='plc_agent.process_contracts.ProcessContract:'+tid
        path.write_text(json.dumps(t,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    tasks=load_tasks();report=validate(tasks)
    if report['errors']:raise ValueError(report['errors'])
    path=ROOT/'dataset_versions/v2_revision_manifest.json';m=json.loads(path.read_text(encoding='utf-8'));m['validation']=report
    for t in tasks:next(c for c in m['changes'] if c['id']==t['id'])['after_sha256']=digest(t)
    path.write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(report,ensure_ascii=False))
if __name__=='__main__':main()
